import{_ as o,I as e,o as p,c,b6 as l,j as a,J as s,w as n,a as i}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"類 Dify 智能體平臺開發實戰","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/assignments/custom-dify-agent-platform/index.md","filePath":"zh-tw/stage-2/assignments/custom-dify-agent-platform/index.md"}'),b={name:"zh-tw/stage-2/assignments/custom-dify-agent-platform/index.md"},u={style:{margin:"32px 0"}};function k(g,t,f,m,_,E){const r=e("StepBar"),d=e("ClientOnly"),h=e("el-card");return p(),c("div",null,[t[2]||(t[2]=l('<h1 id="類-dify-智能體平臺開發實戰" tabindex="-1">類 Dify 智能體平臺開發實戰 <a class="header-anchor" href="#類-dify-智能體平臺開發實戰" aria-label="Permalink to “類 Dify 智能體平臺開發實戰”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本實戰項目要求你圍繞一份真實的 PRD，從零完成一個模仿 Dify 核心體驗的智能體平臺。你將構建用戶控制檯、管理後臺和平臺後端，實現智能體管理、對話、日誌和知識庫等核心功能。</p><p>這是 Stage 2 的綜合實戰環節。與前面的單頁面或單功能項目不同，這個項目要求你構建一個有&quot;平臺感&quot;的 AI 產品——包含多角色、多模塊、資料持久化和模型調用鏈路。</p><h2 id="前置知識" tabindex="-1">前置知識 <a class="header-anchor" href="#前置知識" aria-label="Permalink to “前置知識”">​</a></h2><p>在開始本項目之前，你應該已經掌握以下內容：</p><ul><li>前端頁面設計與組件庫使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">現代組件庫</a>）</li><li>後端接口設計與開發（<a href="./../../backend/ai-interface-code/">接口程式碼編寫</a>）</li><li>資料庫基礎與 Supabase（<a href="./../../backend/database-supabase/">從資料庫到 Supabase</a>）</li><li>Git 工作流與部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 應用</a>）</li></ul><h2 id="學習目標" tabindex="-1">學習目標 <a class="header-anchor" href="#學習目標" aria-label="Permalink to “學習目標”">​</a></h2><p>完成本實戰後，你將能夠：</p><ol><li>閱讀並理解一份真實的 PRD，從中提取開發任務清單</li><li>設計智能體平臺的頁面架構和資料模型</li><li>實現智能體創建、對話、日誌記錄的完整鏈路</li><li>使用 AI 輔助完成平臺型產品開發</li><li>完成端到端聯調，交付一個可演示的 AI 平臺原型</li></ol><h2 id="項目簡介" tabindex="-1">項目簡介 <a class="header-anchor" href="#項目簡介" aria-label="Permalink to “項目簡介”">​</a></h2><p>你要構建的產品是一個類 Dify 智能體平臺，包含兩個子系統：</p><table tabindex="0"><thead><tr><th>子系統</th><th>職責</th></tr></thead><tbody><tr><td><strong>用戶控制檯</strong></td><td>創建智能體、配置 Prompt、發起對話、查看日誌、管理知識庫</td></tr><tr><td><strong>管理後臺</strong></td><td>查看用戶資料、平臺資源使用情況、調用統計</td></tr></tbody></table><p>後端需要支持以下核心能力：智能體管理、會話管理、消息存儲、模型調用、調用日誌記錄、知識庫接入。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本項目的需求文檔在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-tw/stage-2/assignments/custom-dify-agent-platform/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',15)),a("div",u,[s(d,null,{default:n(()=>[s(r,{active:0,items:[{title:"需求分析",description:"閱讀 PRD，明確頁面、能力邊界、鑑權、資料模型"},{title:"搭建骨架",description:"用 AI 生成用戶控制檯和管理後臺骨架"},{title:"迭代開發",description:"逐模塊補充智能體、對話、日誌、知識庫"},{title:"聯調上線",description:"端到端跑通，部署並準備演示"}]})]),_:1})]),t[3]||(t[3]=l(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-閱讀-prd" tabindex="-1">1.1 閱讀 PRD <a class="header-anchor" href="#_1-1-閱讀-prd" aria-label="Permalink to “1.1 閱讀 PRD”">​</a></h3><p>打開 PRD 文檔，重點回答以下問題：</p><ul><li>智能體、會話、日誌、知識庫哪些要進 MVP？</li><li>頁面和路由清單是否拍板？</li><li>模型調用和日誌記錄的邊界是什麼？</li><li>多租戶和複雜工作流是否先不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上問題沒有明確答案，不要開始寫程式碼。需求理解不清楚是導致返工的最常見原因。</p></div><h3 id="_1-2-確認系統架構" tabindex="-1">1.2 確認系統架構 <a class="header-anchor" href="#_1-2-確認系統架構" aria-label="Permalink to “1.2 確認系統架構”">​</a></h3><p>根據 PRD 梳理出系統的整體架構：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; app[&quot;用戶控制檯&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;管理後臺&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;鑑權&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; agent[&quot;智能體配置&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; chat[&quot;會話對話&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; llm[&quot;模型調用&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; db[&quot;資料庫&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; kb[&quot;知識庫接入&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; logs[&quot;調用日誌與平臺概覽&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logs --&gt; db</span></span></code></pre></div><h2 id="第二部分-搭建項目骨架" tabindex="-1">第二部分：搭建項目骨架 <a class="header-anchor" href="#第二部分-搭建項目骨架" aria-label="Permalink to “第二部分：搭建項目骨架”">​</a></h2><h3 id="_2-1-生成前端頁面" tabindex="-1">2.1 生成前端頁面 <a class="header-anchor" href="#_2-1-生成前端頁面" aria-label="Permalink to “2.1 生成前端頁面”">​</a></h3><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請基於當前 PRD，幫我生成一個類 Dify 智能體平臺的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 用戶側包括：登錄、智能體列表、智能體配置、對話頁、日誌頁、知識庫頁</span></span>
<span class="line"><span>2. 後臺側包括：後臺首頁、用戶概覽、資源使用概覽</span></span>
<span class="line"><span>3. 先只生成頁面結構和假資料，不接真實接口</span></span>
<span class="line"><span>4. 風格要像現代 AI 平臺</span></span></code></pre></div><h3 id="_2-2-驗證頁面結構" tabindex="-1">2.2 驗證頁面結構 <a class="header-anchor" href="#_2-2-驗證頁面結構" aria-label="Permalink to “2.2 驗證頁面結構”">​</a></h3><p>逐項檢查：</p><ul><li>[ ] 用戶控制檯和管理後臺入口是否分開</li><li>[ ] 智能體列表、配置、對話、日誌、知識庫頁面是否完整</li><li>[ ] 管理後臺首頁、用戶概覽頁面是否可訪問</li><li>[ ] 假資料展示了基本的 UI 狀態</li></ul><h2 id="第三部分-迭代開發" tabindex="-1">第三部分：迭代開發 <a class="header-anchor" href="#第三部分-迭代開發" aria-label="Permalink to “第三部分：迭代開發”">​</a></h2><h3 id="_3-1-按模塊推進" tabindex="-1">3.1 按模塊推進 <a class="header-anchor" href="#_3-1-按模塊推進" aria-label="Permalink to “3.1 按模塊推進”">​</a></h3><p>在骨架的基礎上，按以下順序逐模塊補充功能：</p><ol><li><strong>鑑權</strong>：註冊、登錄、角色區分</li><li><strong>智能體管理</strong>：創建、編輯、刪除、Prompt 配置</li><li><strong>對話功能</strong>：會話創建、消息收發、模型調用</li><li><strong>日誌記錄</strong>：耗時、token 用量、錯誤記錄</li><li><strong>知識庫接入</strong>（加分項）：文檔上傳、檢索、結果注入</li><li><strong>管理後臺</strong>：用戶資料、資源使用、調用統計</li></ol><p>每完成一個模塊，使用下表進行自檢：</p><table tabindex="0"><thead><tr><th>檢查項</th><th>驗證方法</th></tr></thead><tbody><tr><td>頁面一致性</td><td>頁面數量、功能是否符合 PRD</td></tr><tr><td>接口閉環</td><td>agents、chat、logs、knowledge 接口是否完整</td></tr><tr><td>權限隔離</td><td>用戶是否只能管理自己的 agent 和會話</td></tr><tr><td>資料一致性</td><td>messages、logs、documents 資料是否對得上</td></tr><tr><td>可演示性</td><td>是否能演示&quot;創建 agent → 對話 → 查看日誌&quot;完整鏈路</td></tr></tbody></table><h3 id="_3-2-知識庫接入-加分項" tabindex="-1">3.2 知識庫接入（加分項） <a class="header-anchor" href="#_3-2-知識庫接入-加分項" aria-label="Permalink to “3.2 知識庫接入（加分項）”">​</a></h3><p>如果你想增加知識庫能力，可以給每個智能體增加一個&quot;知識庫開關&quot;：</p><ul><li>開啟後先檢索知識片段，再和用戶問題一起發送給模型</li><li>關閉後按普通對話模式響應</li></ul><p>第一版不必追求複雜 RAG，只要有&quot;檢索結果可見、調用鏈路可解釋&quot;即可。</p><h2 id="第四部分-聯調與上線" tabindex="-1">第四部分：聯調與上線 <a class="header-anchor" href="#第四部分-聯調與上線" aria-label="Permalink to “第四部分：聯調與上線”">​</a></h2><h3 id="_4-1-端到端測試" tabindex="-1">4.1 端到端測試 <a class="header-anchor" href="#_4-1-端到端測試" aria-label="Permalink to “4.1 端到端測試”">​</a></h3><p>至少驗證以下場景：</p><ul><li>註冊 → 創建智能體 → 配置 Prompt → 發起對話 → 查看日誌</li><li>管理員登錄 → 查看用戶資料 → 查看調用統計</li></ul><p>部署前檢查：</p><ul><li>[ ] 所有核心接口都做了登錄校驗</li><li>[ ] 智能體歸屬權限檢查通過</li><li>[ ] 會話記錄、日誌記錄真實落庫</li><li>[ ] 模型 Key 使用環境變量，不硬編碼</li><li>[ ] 錯誤提示可在前端看到，不只打控制檯</li></ul><h3 id="_4-2-部署" tabindex="-1">4.2 部署 <a class="header-anchor" href="#_4-2-部署" aria-label="Permalink to “4.2 部署”">​</a></h3><p>將項目部署到公網環境。部署教程參考：<a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a>、<a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a>。</p><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本項目後，你需要提交以下內容：</p><ul><li>[ ] 可訪問的線上演示鏈接</li><li>[ ] 源碼倉庫鏈接（含 README）</li><li>[ ] PRD 文檔</li><li>[ ] 核心頁面截圖（智能體管理頁、對話頁、日誌頁、後臺首頁）</li><li>[ ] 60 秒演示影片（覆蓋創建智能體 → 對話 → 查看日誌）</li></ul><p>README 至少包含：項目簡介、架構說明、技術棧、本地啟動步驟、環境變量清單、接口說明。</p><h2 id="評分標準" tabindex="-1">評分標準 <a class="header-anchor" href="#評分標準" aria-label="Permalink to “評分標準”">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>基本要求</th><th>進階要求</th></tr></thead><tbody><tr><td>平臺完整度</td><td>agents / chat / logs 三頁可用</td><td>有清晰導航與統一設計語言</td></tr><tr><td>業務閉環</td><td>可創建智能體並真實對話</td><td>支持多智能體切換與歷史會話</td></tr><tr><td>資料與追蹤</td><td>消息與調用日誌可查詢</td><td>有 token / 耗時統計看板</td></tr><tr><td>權限安全</td><td>僅登錄用戶可訪問核心接口</td><td>資源歸屬校驗完善</td></tr><tr><td>工程交付</td><td>可部署、可演示、README 清晰</td><td>接入知識庫並可解釋檢索結果</td></tr></tbody></table><h2 id="提交前檢查" tabindex="-1">提交前檢查 <a class="header-anchor" href="#提交前檢查" aria-label="Permalink to “提交前檢查”">​</a></h2>`,40)),s(h,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:n(()=>[...t[0]||(t[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"提交前最後看一眼",-1)])]),default:n(()=>[t[1]||(t[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 登錄後可訪問智能體管理、對話、日誌頁面")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 至少可以創建 1 個智能體併成功對話")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 每輪問答都能在資料庫查到記錄")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 調用失敗時前端可見錯誤資訊且日誌已記錄")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 項目已部署，README 和演示影片齊全")])])],-1))]),_:1}),t[4]||(t[4]=l('<h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型輔助編寫接口程式碼與接口文檔</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a></li></ul>',2))])}const x=o(b,[["render",k]]);export{P as __pageData,x as default};
